<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// activation planes → PlaneGeometry(3,3) pale translucent horizontal squares
// plane outlines → LineLoop dark grey square rims at seven Y levels
// active plane outline → LineLoop bright amber rim for selected forward-pass layer
// corner guides → LineSegments faint grey vertical connectors between plane corners
// outer envelope → dashed grey Line polylines around maximum trajectory spread
// datapoints → SphereGeometry(0.045) red/blue markers on every plane
// trajectories → dashed cubic-sampled Line curves red/blue through all layers
// active incoming segments → brighter dashed Line curves into selected target layer
// hover trace → enlarged spheres plus bright Line following one datapoint ID
// legend arrows → black Line plus ConeGeometry arrowheads in six layer gaps
// legend labels → addLabel rounded white boxes: linear/relu/linear/relu/linear/softmax
// training axis → screen-horizontal Line, ConeGeometry arrowhead, tick spheres, ellipsis labels

const layerY = [0, 1.15, 2.30, 3.45, 4.60, 5.75, 6.90];
const layerNames = ['input', 'linear1', 'relu1', 'linear2', 'relu2', 'linear3', 'softmax'];
const opNames = ['linear', 'relu', 'linear', 'relu', 'linear', 'softmax'];
const keyIters = [0, 33, 66, 100];
const classInfo = {
  red: { color: 0xff2020, hex: '#ff2020' },
  blue: { color: 0x1e35ff, hex: '#1e35ff' }
};
const N = 32;
let trainingIteration = 0;
let forwardPassLayer = 'allLayers';
let hoverClass = null;
let hoverIndex = -1;

function mulberry32(seed) {
  return function () {
    let t = seed += 0x6D2B79F5;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(202405);
function gaussian() {
  const u = Math.max(rand(), 1e-6);
  const v = Math.max(rand(), 1e-6);
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function v3FromXZ(x, y, z) { return new THREE.Vector3(x, y, z); }

const baseXZ = { red: [], blue: [] };
for (const cls of ['red', 'blue']) {
  for (let i = 0; i < N; i++) {
    const r = Math.min(0.65, Math.abs(0.26 + 0.18 * gaussian()));
    const a = rand() * Math.PI * 2;
    baseXZ[cls].push({
      x: r * Math.cos(a) + 0.06 * gaussian(),
      z: r * Math.sin(a) + 0.06 * gaussian(),
      phase: rand() * Math.PI * 2,
      jitter: gaussian()
    });
  }
}

const keyPositions = {};
for (const cls of ['red', 'blue']) {
  keyPositions[cls] = [];
  for (let i = 0; i < N; i++) keyPositions[cls][i] = [];
}

function makeKeyPosition(cls, i, layer, p) {
  const b = baseXZ[cls][i];
  if (layer === 0) return v3FromXZ(b.x, layerY[layer], b.z);
  const lfRaw = [0, 0.15, 0.28, 0.43, 0.60, 0.84, 1.0][layer];
  const lf = lfRaw;
  const wiggle = Math.sin(b.phase + layer * 0.9) * 0.055 * (1 - 0.25 * lf);
  const kink = (layer === 2 || layer === 4) ? Math.max(0, b.x + 0.15) * 0.18 * (0.25 + p) : 0;
  let x, z;
  if (cls === 'red') {
    const meanX = ((-0.15 * (1 - p)) + (-0.45 * p)) * lf;
    const meanZ = ((-0.05 * (1 - p)) + (-0.10 * p)) * lf;
    const spread = 1 - 0.35 * lf - 0.38 * p * lf;
    x = meanX + b.x * spread * 0.58 + wiggle - 0.04 * Math.sin(layer + i);
    z = meanZ + b.z * spread * 0.58 - 0.04 * Math.cos(b.phase + layer) - kink * 0.2;
  } else {
    const meanX = ((0.20 * (1 - p)) + (1.25 * p)) * Math.pow(lf, 1.08);
    const meanZ = ((0.15 * (1 - p)) + (0.85 * p)) * Math.pow(lf, 1.13);
    const spread = 0.82 - 0.14 * lf + 0.08 * p;
    const bow = p * Math.pow(lf, 1.7);
    x = meanX + b.x * spread * 0.75 + wiggle + 0.16 * bow * Math.sin(b.phase);
    z = meanZ + b.z * spread * 0.75 + 0.10 * bow * Math.cos(b.phase * 0.7) + kink;
  }
  const y = layerY[layer];
  return v3FromXZ(x, y, z);
}

for (const cls of ['red', 'blue']) {
  for (let i = 0; i < N; i++) {
    for (let k = 0; k < keyIters.length; k++) {
      const p = keyIters[k] / 100;
      const arr = [];
      for (let l = 0; l < layerY.length; l++) arr.push(makeKeyPosition(cls, i, l, p));
      keyPositions[cls][i][k] = arr;
    }
  }
}

function interpolatedLayerPositions(cls, i, iter) {
  let a = 0;
  while (a < keyIters.length - 2 && iter > keyIters[a + 1]) a++;
  const b = Math.min(a + 1, keyIters.length - 1);
  const t = (iter - keyIters[a]) / Math.max(1e-6, keyIters[b] - keyIters[a]);
  const smooth = t * t * (3 - 2 * t);
  const out = [];
  for (let l = 0; l < layerY.length; l++) {
    out.push(keyPositions[cls][i][a][l].clone().lerp(keyPositions[cls][i][b][l], smooth));
  }
  return out;
}

const planeFillMat = new THREE.MeshBasicMaterial({
  color: 0xf7f7f7, transparent: true, opacity: 0.12, side: THREE.DoubleSide, depthWrite: false
});
const outlineMat = new THREE.LineBasicMaterial({ color: 0x3d3d3d, transparent: true, opacity: 0.95 });
const outlineDimMat = new THREE.LineBasicMaterial({ color: 0x777777, transparent: true, opacity: 0.25 });
const guideMat = new THREE.LineDashedMaterial({ color: 0x9c9c9c, transparent: true, opacity: 0.35, dashSize: 0.09, gapSize: 0.07 });
const envelopeMat = new THREE.LineDashedMaterial({ color: 0x8d8d8d, transparent: true, opacity: 0.28, dashSize: 0.10, gapSize: 0.08 });
const activePlaneMat = new THREE.LineBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 1 });

const planeOutlines = [];
const planeFills = [];
const half = 1.5;
function squarePts(y, scale = 1) {
  const h = half * scale;
  return [
    new THREE.Vector3(-h, y, -h), new THREE.Vector3(h, y, -h),
    new THREE.Vector3(h, y, h), new THREE.Vector3(-h, y, h),
    new THREE.Vector3(-h, y, -h)
  ];
}
for (const y of layerY) {
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(3, 3), planeFillMat.clone());
  fill.rotation.x = -Math.PI / 2;
  fill.position.y = y;
  scene.add(fill);
  planeFills.push(fill);

  const rim = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(squarePts(y).slice(0, 4)),
    outlineMat.clone()
  );
  scene.add(rim);
  planeOutlines.push(rim);
}
const activePlane = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(squarePts(layerY[0], 1.035).slice(0, 4)),
  activePlaneMat
);
activePlane.visible = false;
scene.add(activePlane);

const guidePts = [];
const corners = [[-half, -half], [half, -half], [half, half], [-half, half]];
for (const [x, z] of corners) {
  for (let l = 0; l < layerY.length - 1; l++) {
    guidePts.push(new THREE.Vector3(x, layerY[l], z), new THREE.Vector3(x, layerY[l + 1], z));
  }
}
const guides = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(guidePts), guideMat);
guides.computeLineDistances();
scene.add(guides);

const envelopeLines = [];
const envSpecs = [
  [[-0.85, -0.65], [-0.75, -0.45], [-0.60, -0.30], [-0.45, -0.18], [-0.55, -0.12], [-0.55, -0.10], [-0.55, -0.10]],
  [[0.75, 0.65], [0.75, 0.70], [0.88, 0.82], [1.10, 0.96], [1.35, 1.05], [1.62, 1.14], [1.72, 1.18]],
  [[-0.75, 0.70], [-0.62, 0.55], [-0.48, 0.42], [-0.32, 0.32], [-0.20, 0.22], [-0.12, 0.16], [-0.10, 0.14]],
  [[0.65, -0.70], [0.76, -0.35], [0.86, -0.05], [1.02, 0.25], [1.18, 0.50], [1.35, 0.72], [1.45, 0.88]]
];
for (const spec of envSpecs) {
  const pts = spec.map((xz, l) => new THREE.Vector3(xz[0], layerY[l], xz[1]));
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), envelopeMat.clone());
  line.computeLineDistances();
  scene.add(line);
  envelopeLines.push(line);
}

const dotGeo = new THREE.SphereGeometry(0.045, 12, 8);
const dotMats = {
  red: {
    normal: new THREE.MeshBasicMaterial({ color: classInfo.red.color, transparent: true, opacity: 0.82 }),
    dim: new THREE.MeshBasicMaterial({ color: classInfo.red.color, transparent: true, opacity: 0.23 }),
    active: new THREE.MeshBasicMaterial({ color: classInfo.red.color, transparent: true, opacity: 1 })
  },
  blue: {
    normal: new THREE.MeshBasicMaterial({ color: classInfo.blue.color, transparent: true, opacity: 0.82 }),
    dim: new THREE.MeshBasicMaterial({ color: classInfo.blue.color, transparent: true, opacity: 0.23 }),
    active: new THREE.MeshBasicMaterial({ color: classInfo.blue.color, transparent: true, opacity: 1 })
  }
};

const pointMeshes = [];
const pointsByClass = { red: [], blue: [] };
for (const cls of ['red', 'blue']) {
  for (let i = 0; i < N; i++) {
    pointsByClass[cls][i] = [];
    for (let l = 0; l < layerY.length; l++) {
      const m = new THREE.Mesh(dotGeo, dotMats[cls].normal);
      m.userData.pointClass = cls;
      m.userData.pointIndex = i;
      m.userData.layer = l;
      scene.add(m);
      pointMeshes.push(m);
      pointsByClass[cls][i][l] = m;
      registerInteractive(m, {
        title: `${cls} example ${i + 1}`,
        tooltip: 'Hover traces this same datapoint through every layer',
        body: 'The enlarged markers show one example being carried continuously through the stack of layer activations.'
      });
    }
  }
}

function makeTrajMat(cls, opacity, bright = false) {
  return new THREE.LineDashedMaterial({
    color: bright ? 0xffffff : classInfo[cls].color,
    transparent: true,
    opacity,
    dashSize: bright ? 0.08 : 0.075,
    gapSize: bright ? 0.045 : 0.055
  });
}

const trajLines = { red: [], blue: [] };
const segmentLines = { red: [], blue: [] };
for (const cls of ['red', 'blue']) {
  for (let i = 0; i < N; i++) {
    const line = new THREE.Line(new THREE.BufferGeometry(), makeTrajMat(cls, 0.55));
    scene.add(line);
    trajLines[cls][i] = line;

    const seg = new THREE.Line(new THREE.BufferGeometry(), makeTrajMat(cls, 0.95));
    seg.visible = false;
    scene.add(seg);
    segmentLines[cls][i] = seg;
  }
}

function curveBetween(a, b, cls, layerIn, iter) {
  const pts = [];
  const p = iter / 100;
  const dir = b.clone().sub(a);
  const c1 = a.clone().addScaledVector(dir, 0.33);
  const c2 = a.clone().addScaledVector(dir, 0.67);
  if (cls === 'blue') {
    const bow = p * Math.pow((layerIn + 1) / 6, 1.4);
    c1.x += 0.10 * bow; c1.z += 0.08 * bow;
    c2.x += 0.20 * bow; c2.z += 0.14 * bow;
  } else {
    const pinch = p * 0.045 * (layerIn + 1);
    c1.x -= pinch; c2.x -= pinch * 0.45;
    c1.z -= pinch * 0.18; c2.z -= pinch * 0.10;
  }
  for (let s = 0; s <= 8; s++) {
    const t = s / 8;
    const mt = 1 - t;
    pts.push(new THREE.Vector3(
      mt * mt * mt * a.x + 3 * mt * mt * t * c1.x + 3 * mt * t * t * c2.x + t * t * t * b.x,
      mt * mt * mt * a.y + 3 * mt * mt * t * c1.y + 3 * mt * t * t * c2.y + t * t * t * b.y,
      mt * mt * mt * a.z + 3 * mt * mt * t * c1.z + 3 * mt * t * t * c2.z + t * t * t * b.z
    ));
  }
  return pts;
}

const currentPositions = { red: [], blue: [] };
function fullCurvePoints(cls, i, positions) {
  const pts = [];
  for (let l = 0; l < layerY.length - 1; l++) {
    const seg = curveBetween(positions[l], positions[l + 1], cls, l, trainingIteration);
    if (l > 0) seg.shift();
    pts.push(...seg);
  }
  return pts;
}

function replaceLinePoints(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  line.computeLineDistances();
  old?.dispose?.();
}

const hoverGroup = new THREE.Group();
const hoverLine = new THREE.Line(
  new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x111111, transparent: true, opacity: 0.9 })
);
hoverGroup.add(hoverLine);
const hoverMarkerGeo = new THREE.SphereGeometry(0.085, 16, 10);
const hoverMarkers = [];
for (let l = 0; l < layerY.length; l++) {
  const hm = new THREE.Mesh(hoverMarkerGeo, new THREE.MeshBasicMaterial({ color: 0xffff00 }));
  hoverGroup.add(hm);
  hoverMarkers.push(hm);
}
hoverGroup.visible = false;
scene.add(hoverGroup);

function updateHoverTrace() {
  if (hoverClass == null || hoverIndex < 0) {
    hoverGroup.visible = false;
    return;
  }
  const pos = currentPositions[hoverClass]?.[hoverIndex];
  if (!pos) return;
  hoverGroup.visible = true;
  replaceLinePoints(hoverLine, fullCurvePoints(hoverClass, hoverIndex, pos));
  hoverLine.material.color.set(classInfo[hoverClass].color);
  hoverLine.material.opacity = 1;
  for (let l = 0; l < layerY.length; l++) {
    hoverMarkers[l].position.copy(pos[l]);
    hoverMarkers[l].material.color.set(classInfo[hoverClass].color);
  }
}

const layerToIndex = Object.fromEntries(layerNames.map((n, i) => [n, i]));

function refreshStyles() {
  const selectedLayer = forwardPassLayer === 'allLayers' ? -1 : layerToIndex[forwardPassLayer];
  for (let l = 0; l < layerY.length; l++) {
    const active = selectedLayer === l;
    planeOutlines[l].material = forwardPassLayer === 'allLayers' || active ? outlineMat.clone() : outlineDimMat.clone();
    planeFills[l].material.opacity = active ? 0.24 : (forwardPassLayer === 'allLayers' ? 0.12 : 0.055);
  }

  if (selectedLayer >= 0) {
    activePlane.visible = true;
    activePlane.geometry.dispose();
    activePlane.geometry = new THREE.BufferGeometry().setFromPoints(squarePts(layerY[selectedLayer], 1.04).slice(0, 4));
  } else {
    activePlane.visible = false;
  }

  for (const cls of ['red', 'blue']) {
    for (let i = 0; i < N; i++) {
      const isHover = cls === hoverClass && i === hoverIndex;
      trajLines[cls][i].material.opacity = forwardPassLayer === 'allLayers' ? (isHover ? 0.88 : 0.55) : (isHover ? 0.46 : 0.16);
      segmentLines[cls][i].visible = selectedLayer > 0;
      segmentLines[cls][i].material.opacity = selectedLayer > 0 ? (isHover ? 1 : 0.86) : 0;
      for (let l = 0; l < layerY.length; l++) {
        const mesh = pointsByClass[cls][i][l];
        const dotActive = selectedLayer < 0 || selectedLayer === l || (selectedLayer > 0 && l === selectedLayer - 1);
        mesh.material = isHover ? dotMats[cls].active : (dotActive ? dotMats[cls].normal : dotMats[cls].dim);
        mesh.scale.setScalar(isHover ? 1.5 : 1);
      }
    }
  }

  document.querySelectorAll('#forwardPassLayerButtons button').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.layer === forwardPassLayer);
  });
}

function updateTrainingGeometry() {
  document.getElementById('trainingIterationValue').textContent = String(Math.round(trainingIteration));
  for (const cls of ['red', 'blue']) {
    for (let i = 0; i < N; i++) {
      const pos = interpolatedLayerPositions(cls, i, trainingIteration);
      currentPositions[cls][i] = pos;
      for (let l = 0; l < layerY.length; l++) pointsByClass[cls][i][l].position.copy(pos[l]);
      replaceLinePoints(trajLines[cls][i], fullCurvePoints(cls, i, pos));

      const selectedLayer = forwardPassLayer === 'allLayers' ? -1 : layerToIndex[forwardPassLayer];
      if (selectedLayer > 0) {
        replaceLinePoints(segmentLines[cls][i], curveBetween(pos[selectedLayer - 1], pos[selectedLayer], cls, selectedLayer - 1, trainingIteration));
      }
    }
  }
  updateHoverTrace();
  updateAxisTicks();
  refreshStyles();
}

const screenRight = new THREE.Vector3(1, 0, -1).normalize();

function makeLine(points, material) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), material);
}

const legendBase = screenRight.clone().multiplyScalar(-3.20);
legendBase.z += 0.05;
for (let gap = 0; gap < 6; gap++) {
  const y0 = layerY[gap] + 0.12;
  const y1 = layerY[gap + 1] - 0.12;
  const x = legendBase.x;
  const z = legendBase.z;
  const arrowLine = makeLine([new THREE.Vector3(x, y0, z), new THREE.Vector3(x, y1 - 0.10, z)], new THREE.LineBasicMaterial({ color: 0x000000 }));
  scene.add(arrowLine);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.065, 0.18, 16), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  cone.position.set(x, y1, z);
  scene.add(cone);
}

const axisGroup = new THREE.Group();
const axisY = -0.68;
const axisCenter = new THREE.Vector3(-0.30, axisY, 0.78);
const axisStart = axisCenter.clone().addScaledVector(screenRight, -2.75);
const axisEnd = axisCenter.clone().addScaledVector(screenRight, 2.95);
const axisLine = makeLine([axisStart, axisEnd], new THREE.LineBasicMaterial({ color: 0x000000 }));
axisGroup.add(axisLine);
const axisCone = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.24, 18), new THREE.MeshBasicMaterial({ color: 0x000000 }));
axisCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), screenRight);
axisCone.position.copy(axisEnd).addScaledVector(screenRight, 0.07);
axisGroup.add(axisCone);
scene.add(axisGroup);

const tickMeshes = [];
const tickGeo = new THREE.SphereGeometry(0.06, 14, 10);
for (let k = 0; k < 4; k++) {
  const t = k / 3;
  const pos = axisStart.clone().lerp(axisEnd, 0.10 + 0.78 * t);
  const tick = new THREE.Mesh(tickGeo, new THREE.MeshBasicMaterial({ color: 0x444444 }));
  tick.position.copy(pos);
  scene.add(tick);
  tickMeshes.push(tick);
}
function updateAxisTicks() {
  const nearest = keyIters.reduce((best, val, idx) => Math.abs(val - trainingIteration) < Math.abs(keyIters[best] - trainingIteration) ? idx : best, 0);
  tickMeshes.forEach((m, idx) => {
    m.material.color.set(idx === nearest ? 0xffaa00 : 0x444444);
    m.scale.setScalar(idx === nearest ? 1.55 : 1);
  });
}

const labelEntries = [];
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.72 });

for (let gap = 0; gap < 6; gap++) {
  const entry = addLabel(opNames[gap], new THREE.Vector3(legendBase.x, (layerY[gap] + layerY[gap + 1]) / 2, legendBase.z), {
    fontSize: '15px',
    background: '#ffffff',
    offset: [0, 0]
  });
  entry.div.style.border = '2px solid #000';
  entry.div.style.borderRadius = '8px';
  entry.div.style.padding = '2px 8px';
  entry.div.style.fontFamily = 'ui-monospace, Menlo, Consolas, monospace';
  labelEntries.push(entry);
}

addLabel('Training iteration', axisStart.clone().addScaledVector(screenRight, -0.46).add(new THREE.Vector3(0, -0.02, 0)), {
  fontSize: '18px',
  bold: true,
  offset: [0, 10]
});
addLabel('&bull;&nbsp;&bull;&nbsp;&bull;', axisStart.clone().lerp(axisEnd, 0.43).add(new THREE.Vector3(0, 0.015, 0)), {
  fontSize: '22px',
  bold: true,
  offset: [0, 7]
});
addLabel('&bull;&nbsp;&bull;&nbsp;&bull;', axisStart.clone().lerp(axisEnd, 0.70).add(new THREE.Vector3(0, 0.015, 0)), {
  fontSize: '22px',
  bold: true,
  offset: [0, 7]
});

const localRaycaster = new THREE.Raycaster();
const localPointer = new THREE.Vector2();
canvas.addEventListener('pointermove', (event) => {
  const rect = canvas.getBoundingClientRect();
  localPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  localPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  localRaycaster.setFromCamera(localPointer, camera);
  const hits = localRaycaster.intersectObjects(pointMeshes, false);
  if (hits.length) {
    const obj = hits[0].object;
    if (hoverClass !== obj.userData.pointClass || hoverIndex !== obj.userData.pointIndex) {
      hoverClass = obj.userData.pointClass;
      hoverIndex = obj.userData.pointIndex;
      updateHoverTrace();
      refreshStyles();
    }
    showTooltip(`${hoverClass} datapoint ${hoverIndex + 1}: same example on all seven planes`, event);
  } else if (hoverClass !== null) {
    hoverClass = null;
    hoverIndex = -1;
    updateHoverTrace();
    refreshStyles();
  }
});
canvas.addEventListener('pointerleave', () => {
  hoverClass = null;
  hoverIndex = -1;
  updateHoverTrace();
  refreshStyles();
});

document.getElementById('trainingIteration').addEventListener('input', (e) => {
  trainingIteration = Number(e.target.value);
  updateTrainingGeometry();
});
document.querySelectorAll('#forwardPassLayerButtons button').forEach(btn => {
  btn.addEventListener('click', () => {
    forwardPassLayer = btn.dataset.layer;
    updateTrainingGeometry();
  });
});

const demoSteps = [
  { title: 'Early training: tangled representations', state: { trainingIteration: 0, forwardPassLayer: 'allLayers' } },
  { title: 'Follow the first linear map', state: { trainingIteration: 35, forwardPassLayer: 'linear1' } },
  { title: 'Nonlinearity bends the paths', state: { trainingIteration: 65, forwardPassLayer: 'relu2' } },
  { title: 'Late training: clean class separation', state: { trainingIteration: 100, forwardPassLayer: 'softmax' } }
];
let tweenToken = 0;
window.goToStep = function goToStep(stepIndex = 0) {
  const step = demoSteps[Math.max(0, Math.min(demoSteps.length - 1, stepIndex | 0))];
  const startIter = trainingIteration;
  const endIter = step.state.trainingIteration;
  const start = performance.now();
  const token = ++tweenToken;
  forwardPassLayer = step.state.forwardPassLayer;
  document.getElementById('trainingIteration').value = String(Math.round(startIter));
  showPopup(step.title, step.title === demoSteps[0].title
    ? 'At the first training snapshot, red and blue examples begin thoroughly mixed and only weakly separate as they move upward through the network.'
    : step.title === demoSteps[1].title
      ? 'The first linear layer pulls the mixed input cloud into a slanted bundle. Highlighting only the incoming trajectories makes the layer-to-layer deformation easier to read.'
      : step.title === demoSteps[2].title
        ? 'At a ReLU plane, many paths kink or flatten before continuing upward. This shows why the stack is not just one straight linear projection.'
        : 'Near the final training snapshot, the blue trajectories bow far to one side while the red trajectories form a tighter opposing bundle.');
  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - start) / 850);
    const s = t * t * (3 - 2 * t);
    trainingIteration = startIter + (endIter - startIter) * s;
    document.getElementById('trainingIteration').value = String(Math.round(trainingIteration));
    updateTrainingGeometry();
    if (t < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
};
document.querySelectorAll('#demoStepButtons button').forEach(btn => {
  btn.addEventListener('click', () => window.goToStep(Number(btn.dataset.step)));
});

updateTrainingGeometry();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

You are a strict critic of generated interactive Three.js 3D figures against original 2D textbook figure images.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. Ensure that the output is not a 2D image rendered with Three.js. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED. A deterministic verifier has rendered this figure headless at multiple viewports and confirmed it runs without exceptions or console errors with the render loop alive, actually draws to the GPU (non-blank canvas, real geometry, no NaN coordinates), fits the viewport with no overflow and the control panel fully on-screen, and has labels that are on-screen, not enormous, and not heavily overlapping.
Spend NO scores, failure modes, discrepancies, or action items on any of that. Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct geometry, correct primitives, correct camera/view, faithful composition and colors, correct and meaningful labels, meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
- THREE, OrbitControls, renderer, scene, orthographic camera, controls, animate loop, ResizeObserver are all pre-wired
- addLabel(text, position3D, {color, fontSize, bold, offset, background}?) — floating HTML label system
- setStandardView({azimuth, polar, heightFraction}?) — frames the camera to scene content
- Reset View is scaffolded; generated code may add controls, panels, and UI affordances as needed to support the planned interactions

DISCREPANCIES - list 0-6 visual discrepancies between the source figure and the generated figure, prioritized by impact on recognizability and concept accuracy
- Focus on: wrong geometric primitives, missing or incorrect elements, wrong colors, missing or mislabeled annotations, broken or absent interactions
- De-prioritize: minor camera angle differences, exact crop/zoom, whitespace variation — only flag these if they make the figure hard to recognize or misleading
- For multipanel source figures, if the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), check the HTML/JS before flagging a part as "missing" — a part hidden behind an unactivated toggle is not a discrepancy

FAILURE MODES — list any that apply (use empty array [] if none):
"Depth-Wrong"             — 3D depth/perspective interpretation is incorrect
"Missing-Labels"          — important text annotations are absent
"Wrong-Primitives"        — incorrect geometric shapes used for the concept
"Interaction-Broken"      — interactive controls are present but non-functional
"Interaction-Missing"     — no meaningful interactions beyond basic OrbitControls rotation
"Camera-Wrong"            — initial viewpoint differs from the source figure — wrong angle/orientation/rotation, even if all content remains visible
"Scale-Wrong"             — element proportions are noticeably off
"Color-Wrong"             — colors don't match the original figure
"Hallucination"           — elements present that do not appear in the original
"Concept-Misunderstood"   — the core concept being illustrated is    misrepresented

SCORES — integer 1–5 for each field:
geometry_accuracy — Judge these five things:
  • CAMERA — flag "Camera-Wrong" only if the vantage point differs enough to make the figure hard to recognize (reversed foreground/background, a key face hidden, viewed from the opposite side). Minor azimuth/zoom differences do not qualify.
  • PRIMITIVES — flag "Wrong-Primitives" and cap the score when a major element uses the wrong shape (a box drawn as a cone/pyramid, a plane as a disc, a ray as a thick cylinder), even if the composition looks similar.
  • PROJECTION MECHANISM — axonometric = off-axis orthographic, no shear; oblique = front-on orthographic plus a consistent depth shear; perspective = true perspective, used when the source shows convergence or distance-based shrinking.
  • REPEATED ELEMENTS — compare each corresponding element's size and proportions to the source, not just its presence. A set that should visibly vary in size but came out uniform is a spatial error, even if each element is individually a plausible primitive.
  • HARD FLOOR — if the source has genuine 3D structure (elements at different depths, occlusion, a meaningfully three-dimensional arrangement) but the generated figure flattened it into a camera-facing poster with no occlusion or depth falloff, score geometry_accuracy 1 and include "Depth-Wrong", regardless of how correct the colors/labels/elements are. Does NOT apply when the source is itself a flat 2D diagram the plan correctly renders front-on (axis_screen_angles: null).
  5 – All elements represented; plausible positions, connections, proportions
  4 – All major elements present; minor position/alignment issues
  3 – 1-2 elements missing OR noticeable spatial errors; concept still recognizable
  2 – Multiple missing elements OR major spatial errors
  1 – Unrecognizable or completely wrong topology

interactivity_usability — CRITICAL: OrbitControls (mouse drag to rotate/zoom) does NOT count as an interaction. Meaningful interactions = buttons, sliders, toggles, step-through animations, parameter controls built by the developer.
  5 – All planned interactions functional and pedagogically useful; count matches figure complexity (1 deep slider is correct for a single-variable concept; 3+ expected for multi-step figures); demo steps present if the plan includes them
  4 – Most planned interactions functional; minor usability issues; pedagogical value clear
  3 – At least one meaningful interaction works; some planned interactions missing or broken; or interactions only weakly connected to the concept
  2 – Interactions exist in code but broken or no visible effect
  1 – Only OrbitControls present, or no interactions at all — score MUST be 1

faithfulness — Judge overall visual resemblance to the source — composition, geometry, and color scheme at a glance — rather than an exhaustive checklist of small differences. For multipanel source figures where the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), it is correct and expected for only one part to be visible in the default screenshot; check the HTML/JS for a toggle control before penalizing a currently-hidden part as missing or absent. Do not over-penalize extra elements added beyond the source (additional UI chrome, decorative touches) unless they clutter the figure or change its overall look — flag those under the Hallucination failure mode rather than cutting this score for minor additions.
  5 – Clearly recognizable as the same figure: correct geometry, colors, composition, and major labels all present
  4 – Recognizable at a glance; minor differences in color, proportion, or label placement
  3 – General idea clear but notable differences in geometry, composition, or missing elements
  2 – Hard to recognize as the same figure; significant content differences
  1 – Completely different or fabricated

label_quality — Off-screen / heavily-overlapping labels are already caught by the verifier — do not re-flag those. Judge CONTENT (right labels present, correct text, on the correct element, matching the source) and LEGIBILITY (comfortably readable even when the verifier did not call them "enormous", with a deliberate hierarchy — primary labels standing out over axis labels — matching what the source implies).
  5 – All the right labels present, correct text on the correct elements, matching the source, AND sized/styled for easy legibility with a clear hierarchy matching the source
  4 – Content correct; only 1-2 minor issues (content OR sizing/hierarchy — e.g. a label slightly too small or inconsistently sized)
  3 – Half of labels have issues, whether content (wrong text, wrong target, missing, unclear) or legibility (uncomfortably small, inconsistent hierarchy)
  2 – Most labels problematic — mislabeled/missing content, or generally too small/cluttered to read comfortably
  1 – No labels, or all wrong/mislabeled/illegible

concept_accuracy:
  5 – All concepts accurate; interactions demonstrate correct relationships; no misinformation
  4 – Main concept correct; ≤1 minor detail wrong or missing
  3 – Main concept present; 2-3 details wrong or missing
  2 – Significant errors or fabrications; would mislead students
  1 – Completely incorrect or misleading

ACTION ITEMS — separate feedback for the generation and the plan:
- action_items: list 2-4 generation-level fixes (broken controls, wrong primitives, missing labels, scale issues, camera/view correction — things fixable without changing the plan)
- plan_action_items: list 0-2 plan-level fixes (wrong projection_type, missing core elements, wrong interaction type for the concept, fundamental misunderstanding — things requiring a revised plan). Use [] if the plan is sound.

Output this exact JSON structure and nothing else:
{
  "discrepancies": [],
  "failure_modes": [],
  "geometry_accuracy": 3,
  "interactivity_usability": 3,
  "faithfulness": 3,
  "label_quality": 3,
  "concept_accuracy": 3,
  "notes": "one concise sentence summarizing the main strengths and weaknesses",
  "action_items": [
    "Specific generation-level fix 1",
    "Specific generation-level fix 2"
  ],
  "plan_action_items": [
    "Specific plan-level fix 1 (or empty array if plan is sound)"
  ]
}

