// @FIGURE_CODE_BEGIN
// four training snapshots → Groups spaced compactly screen-horizontally along (1,0,-1)
// activation planes → larger faint PlaneGeometry diamonds at seven Y levels
// plane outlines → thick-looking dark LineLoop diamond rims with high render order
// selected plane rims → larger amber LineLoop outlines on the highlighted forward-pass layer
// corner guides → stronger dashed grey LineSegments between corresponding plane corners
// class datapoints → denser SphereGeometry red/blue markers on every plane in every snapshot
// class trajectories → dense, long, opaque dashed Line curves through each point across all network layers
// selected incoming segments → brighter dashed Line curves into the highlighted layer
// hover trace → enlarged spheres plus solid Line following one datapoint through a stack
// operation arrows → bold black CylinderGeometry shafts plus ConeGeometry arrowheads beside the first stack
// operation labels → addLabel rounded boxes: linear/relu/linear/relu/linear/softmax
// training axis → long black Line with ConeGeometry arrowhead, four tick spheres, ellipsis labels

const screenRight = new THREE.Vector3(1, 0, -1).normalize();
const screenDepth = new THREE.Vector3(1, 0, 1).normalize();
const layerY = [0, 0.92, 1.84, 2.76, 3.68, 4.60, 5.52];
const layerNames = ['input', 'linear1', 'relu1', 'linear2', 'relu2', 'linear3', 'softmax'];
const opNames = ['linear', 'relu', 'linear', 'relu', 'linear', 'softmax'];
const layerToIndex = Object.fromEntries(layerNames.map((n, i) => [n, i]));
const snapshotIters = [0, 33, 66, 100];
const snapshotProgress = [0, 0.34, 0.68, 1];
const stackOffsets = [-3.55, -1.18, 1.18, 3.55];
const N = 36;
const half = 1.02;
let highlightedIteration = 0;
let forwardPassLayer = 'allLayers';
let hoverRef = null;

const classInfo = {
  red: { color: 0xff1f1f, hex: '#ff1f1f' },
  blue: { color: 0x253dff, hex: '#253dff' }
};

function rngFactory(seed) {
  return function () {
    let t = seed += 0x6D2B79F5;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = rngFactory(71931);
function gauss() {
  const u = Math.max(rand(), 1e-7);
  const v = Math.max(rand(), 1e-7);
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function centerForSnapshot(s) {
  return screenRight.clone().multiplyScalar(stackOffsets[s]);
}
function toWorld(localX, y, localZ, snap) {
  return centerForSnapshot(snap).add(new THREE.Vector3(localX, y, localZ));
}
function cubic(a, b, c, d, t) {
  const m = 1 - t;
  return a.clone().multiplyScalar(m * m * m)
    .add(b.clone().multiplyScalar(3 * m * m * t))
    .add(c.clone().multiplyScalar(3 * m * t * t))
    .add(d.clone().multiplyScalar(t * t * t));
}

const seeds = { red: [], blue: [] };
for (const cls of ['red', 'blue']) {
  for (let i = 0; i < N; i++) {
    const angle = rand() * Math.PI * 2;
    const radius = Math.min(0.62, Math.abs(0.26 + 0.16 * gauss()));
    seeds[cls].push({
      x: radius * Math.cos(angle) + (cls === 'red' ? 0.07 : -0.07) + 0.025 * gauss(),
      z: radius * Math.sin(angle) + 0.025 * gauss(),
      phase: rand() * Math.PI * 2,
      side: i % 2 ? 1 : -1,
      radial: radius,
      jitter: gauss()
    });
  }
}

function localLayerPosition(cls, i, layer, p) {
  const b = seeds[cls][i];
  const f = layer / 6;
  if (layer === 0) {
    return new THREE.Vector3(
      b.x + (cls === 'blue' ? 0.16 * b.side : 0.035 * b.jitter),
      layerY[layer],
      b.z + (cls === 'red' ? 0.03 * b.side : 0)
    );
  }

  const reluKink = (layer === 2 || layer === 4) ? 0.25 * (0.32 + p) * Math.max(0, b.x + 0.18) : 0;
  const wiggle = 0.055 * Math.sin(b.phase + 0.9 * layer) * (1 - 0.18 * f);

  if (cls === 'blue') {
    const fan = Math.pow(p, 1.05) * Math.pow(f, 1.16);
    const fanSweep = fan * (0.52 + 2.38 * f + 0.34 * Math.sin(b.phase));
    const earlyColumn = 1 - 0.25 * f;
    const spread = earlyColumn + 0.82 * fan + 0.20 * f;
    const x = b.x * spread
      + 0.11 * b.side * (1 - p) * (1 - 0.12 * f)
      + fanSweep
      + 0.20 * fan * b.side
      + wiggle
      + reluKink * 0.72;
    const z = b.z * (0.86 + 0.42 * fan)
      - fanSweep * 0.82
      + fan * (0.24 * Math.cos(0.7 * b.phase) - 0.08)
      + reluKink * 0.18;
    return new THREE.Vector3(x, layerY[layer], z);
  }

  const bundle = Math.pow(p, 1.03) * Math.pow(f, 1.08);
  const redSweep = bundle * (0.34 + 1.22 * f + 0.15 * Math.sin(b.phase));
  const spread = Math.max(0.18, 0.98 - 0.42 * f - 0.28 * bundle);
  const x = b.x * spread
    - redSweep
    - 0.15 * bundle * b.side
    + wiggle * 0.50
    - reluKink * 0.28;
  const z = b.z * spread
    + redSweep * 0.70
    - 0.07 * Math.cos(b.phase + layer)
    - reluKink * 0.18;
  return new THREE.Vector3(x, layerY[layer], z);
}

function positionsFor(snap, cls, i) {
  const p = snapshotProgress[snap];
  const out = [];
  for (let l = 0; l < layerY.length; l++) {
    const q = localLayerPosition(cls, i, l, p);
    out.push(toWorld(q.x, q.y, q.z, snap));
  }
  return out;
}

function curveBetween(a, b, cls, layer, snap) {
  const p = snapshotProgress[snap];
  const dir = b.clone().sub(a);
  const c1 = a.clone().addScaledVector(dir, 0.26);
  const c2 = a.clone().addScaledVector(dir, 0.76);
  if (cls === 'blue') {
    const bow = Math.pow(p, 1.05) * Math.pow((layer + 1) / 6, 1.18);
    c1.addScaledVector(screenRight, 0.10 * bow);
    c2.addScaledVector(screenRight, 0.52 * bow);
    c2.addScaledVector(screenDepth, -0.20 * bow);
  } else {
    const bow = Math.pow(p, 1.06) * Math.pow((layer + 1) / 6, 1.05);
    c1.addScaledVector(screenRight, -0.12 * bow);
    c2.addScaledVector(screenRight, -0.33 * bow);
    c2.addScaledVector(screenDepth, 0.10 * bow);
  }
  const pts = [];
  for (let k = 0; k <= 14; k++) pts.push(cubic(a, c1, c2, b, k / 14));
  return pts;
}

function fullCurve(cls, i, snap) {
  const p = positionsFor(snap, cls, i);
  const pts = [];
  for (let l = 0; l < layerY.length - 1; l++) {
    const seg = curveBetween(p[l], p[l + 1], cls, l, snap);
    if (l > 0) seg.shift();
    pts.push(...seg);
  }
  return pts;
}

function lineFrom(points, material, renderOrder = 1) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), material);
  line.computeLineDistances();
  line.renderOrder = renderOrder;
  return line;
}
function replaceLine(line, points) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(points);
  line.computeLineDistances();
  old?.dispose?.();
}
function squarePoints(snap, y, scale = 1) {
  const c = centerForSnapshot(snap);
  const h = half * scale;
  return [
    c.clone().add(new THREE.Vector3(-h, y, -h)),
    c.clone().add(new THREE.Vector3(h, y, -h)),
    c.clone().add(new THREE.Vector3(h, y, h)),
    c.clone().add(new THREE.Vector3(-h, y, h))
  ];
}

const matPlane = new THREE.MeshBasicMaterial({ color: 0xf7f7f7, transparent: true, opacity: 0.052, side: THREE.DoubleSide, depthWrite: false });
const matRim = new THREE.LineBasicMaterial({ color: 0x3b3b3b, transparent: true, opacity: 1 });
const matGuide = new THREE.LineDashedMaterial({ color: 0x8d8d8d, transparent: true, opacity: 0.62, dashSize: 0.09, gapSize: 0.055, depthWrite: false });
const matActive = new THREE.LineBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 1 });

const dotGeo = new THREE.SphereGeometry(0.036, 12, 9);
const hoverDotGeo = new THREE.SphereGeometry(0.082, 16, 12);
const dotMaterials = {
  red: {
    normal: new THREE.MeshBasicMaterial({ color: classInfo.red.color, transparent: true, opacity: 0.92 }),
    dim: new THREE.MeshBasicMaterial({ color: classInfo.red.color, transparent: true, opacity: 0.22 }),
    active: new THREE.MeshBasicMaterial({ color: classInfo.red.color, transparent: true, opacity: 1 })
  },
  blue: {
    normal: new THREE.MeshBasicMaterial({ color: classInfo.blue.color, transparent: true, opacity: 0.92 }),
    dim: new THREE.MeshBasicMaterial({ color: classInfo.blue.color, transparent: true, opacity: 0.22 }),
    active: new THREE.MeshBasicMaterial({ color: classInfo.blue.color, transparent: true, opacity: 1 })
  }
};
function trajMat(cls, opacity, active = false) {
  return new THREE.LineDashedMaterial({
    color: classInfo[cls].color,
    transparent: true,
    opacity,
    dashSize: active ? 0.07 : 0.052,
    gapSize: active ? 0.030 : 0.036,
    depthWrite: false
  });
}

const allPointMeshes = [];
const snapshots = [];
for (let s = 0; s < 4; s++) {
  const snap = {
    group: new THREE.Group(),
    fills: [],
    rims: [],
    activeRims: [],
    points: { red: [], blue: [] },
    traj: { red: [], blue: [] },
    seg: { red: [], blue: [] }
  };
  scene.add(snap.group);

  for (let l = 0; l < layerY.length; l++) {
    const fill = new THREE.Mesh(new THREE.PlaneGeometry(half * 2, half * 2), matPlane.clone());
    const c = centerForSnapshot(s);
    fill.rotation.x = -Math.PI / 2;
    fill.position.set(c.x, layerY[l], c.z);
    fill.renderOrder = 0;
    snap.group.add(fill);
    snap.fills.push(fill);

    const rim = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(squarePoints(s, layerY[l])), matRim.clone());
    rim.renderOrder = 5;
    snap.group.add(rim);
    snap.rims.push(rim);

    const ar = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(squarePoints(s, layerY[l], 1.06)), matActive.clone());
    ar.visible = false;
    ar.renderOrder = 6;
    snap.group.add(ar);
    snap.activeRims.push(ar);
  }

  const guidePts = [];
  for (const [cx, cz] of [[-half, -half], [half, -half], [half, half], [-half, half]]) {
    for (let l = 0; l < layerY.length - 1; l++) {
      guidePts.push(toWorld(cx, layerY[l], cz, s), toWorld(cx, layerY[l + 1], cz, s));
    }
  }
  const guides = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(guidePts), matGuide.clone());
  guides.computeLineDistances();
  guides.renderOrder = 0;
  snap.group.add(guides);

  for (const cls of ['red', 'blue']) {
    for (let i = 0; i < N; i++) {
      const p = positionsFor(s, cls, i);
      snap.points[cls][i] = [];
      for (let l = 0; l < layerY.length; l++) {
        const m = new THREE.Mesh(dotGeo, dotMaterials[cls].normal);
        m.position.copy(p[l]);
        m.renderOrder = 3;
        m.userData.snap = s;
        m.userData.pointClass = cls;
        m.userData.pointIndex = i;
        m.userData.layer = l;
        snap.group.add(m);
        allPointMeshes.push(m);
        snap.points[cls][i][l] = m;
        registerInteractive(m, {
          title: `${cls} example, snapshot ${snapshotIters[s]}`,
          tooltip: 'Hover traces one example through all layers',
          body: 'Each small marker is the representation of one datapoint at one layer. The dashed path connects the same datapoint through the network.'
        });
      }

      const baseOpacity = s === 3 ? 0.86 : (s === 2 ? 0.80 : 0.70);
      const line = lineFrom(fullCurve(cls, i, s), trajMat(cls, baseOpacity), 2);
      snap.group.add(line);
      snap.traj[cls][i] = line;

      snap.seg[cls][i] = [];
      for (let l = 1; l < layerY.length; l++) {
        const seg = lineFrom(curveBetween(p[l - 1], p[l], cls, l - 1, s), trajMat(cls, 1, true), 4);
        seg.visible = false;
        snap.group.add(seg);
        snap.seg[cls][i][l] = seg;
      }
    }
  }
  snapshots.push(snap);
}

const hoverGroup = new THREE.Group();
const hoverLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x111111, transparent: true, opacity: 0.95, depthWrite: false }));
hoverLine.renderOrder = 7;
hoverGroup.add(hoverLine);
const hoverMarkers = [];
for (let l = 0; l < layerY.length; l++) {
  const hm = new THREE.Mesh(hoverDotGeo, new THREE.MeshBasicMaterial({ color: 0xffff00 }));
  hm.renderOrder = 8;
  hoverGroup.add(hm);
  hoverMarkers.push(hm);
}
hoverGroup.visible = false;
scene.add(hoverGroup);

function updateHoverTrace() {
  if (!hoverRef) {
    hoverGroup.visible = false;
    return;
  }
  const { snap, cls, i } = hoverRef;
  const pts = positionsFor(snap, cls, i);
  replaceLine(hoverLine, fullCurve(cls, i, snap));
  hoverLine.material.color.set(classInfo[cls].color);
  for (let l = 0; l < layerY.length; l++) {
    hoverMarkers[l].position.copy(pts[l]);
    hoverMarkers[l].material.color.set(classInfo[cls].color);
  }
  hoverGroup.visible = true;
}

const labelAnchor = centerForSnapshot(0).addScaledVector(screenRight, -1.78).addScaledVector(screenDepth, -0.04);
const shaftMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
for (let gap = 0; gap < 6; gap++) {
  const y0 = layerY[gap] + 0.18;
  const y1 = layerY[gap + 1] - 0.15;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.017, 0.017, Math.max(0.05, y1 - y0), 12), shaftMat);
  shaft.position.set(labelAnchor.x, (y0 + y1) / 2, labelAnchor.z);
  scene.add(shaft);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.20, 18), shaftMat);
  cone.position.set(labelAnchor.x, y1 + 0.075, labelAnchor.z);
  scene.add(cone);
}

const axisY = -0.52;
const axisStart = centerForSnapshot(0).addScaledVector(screenRight, -0.92).setY(axisY).addScaledVector(screenDepth, 0.88);
const axisEnd = centerForSnapshot(3).addScaledVector(screenRight, 1.18).setY(axisY).addScaledVector(screenDepth, 0.88);
const axisLine = lineFrom([axisStart, axisEnd], new THREE.LineBasicMaterial({ color: 0x000000 }), 4);
scene.add(axisLine);
const axisCone = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.28, 20), new THREE.MeshBasicMaterial({ color: 0x000000 }));
axisCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), screenRight);
axisCone.position.copy(axisEnd).addScaledVector(screenRight, 0.10);
scene.add(axisCone);

const tickGeo = new THREE.SphereGeometry(0.052, 14, 9);
const tickMeshes = [];
for (let s = 0; s < 4; s++) {
  const tick = new THREE.Mesh(tickGeo, new THREE.MeshBasicMaterial({ color: 0x333333 }));
  tick.position.copy(centerForSnapshot(s).setY(axisY).addScaledVector(screenDepth, 0.88));
  scene.add(tick);
  tickMeshes.push(tick);
}

function nearestSnapshotIndex(iter) {
  let best = 0;
  for (let s = 1; s < 4; s++) {
    if (Math.abs(snapshotIters[s] - iter) < Math.abs(snapshotIters[best] - iter)) best = s;
  }
  return best;
}

function refreshStyles() {
  const selected = forwardPassLayer === 'allLayers' ? -1 : layerToIndex[forwardPassLayer];
  const near = nearestSnapshotIndex(highlightedIteration);
  document.getElementById('trainingIterationValue').textContent = String(Math.round(highlightedIteration));

  tickMeshes.forEach((m, s) => {
    m.material.color.set(s === near ? 0xffaa00 : 0x333333);
    m.scale.setScalar(s === near ? 1.75 : 1);
  });

  snapshots.forEach((snap, s) => {
    const emphasized = s === near;
    snap.group.scale.setScalar(emphasized ? 1.025 : 1);
    for (let l = 0; l < layerY.length; l++) {
      const layerActive = selected < 0 || selected === l;
      snap.fills[l].material.opacity = selected === l ? 0.14 : 0.052;
      snap.rims[l].material.opacity = layerActive ? (emphasized ? 1 : 0.88) : 0.34;
      snap.rims[l].material.color.set(layerActive ? 0x383838 : 0x858585);
      snap.activeRims[l].visible = selected === l;
    }

    for (const cls of ['red', 'blue']) {
      for (let i = 0; i < N; i++) {
        const isHover = hoverRef && hoverRef.snap === s && hoverRef.cls === cls && hoverRef.i === i;
        const visibleOpacity = cls === 'blue' && s >= 2 ? 0.88 : 0.76;
        snap.traj[cls][i].material.opacity = selected < 0
          ? (isHover ? 1 : (emphasized ? visibleOpacity : 0.50))
          : (isHover ? 0.62 : 0.18);
        for (let l = 1; l < layerY.length; l++) {
          snap.seg[cls][i][l].visible = selected === l;
          snap.seg[cls][i][l].material.opacity = isHover ? 1 : (emphasized ? 1 : 0.74);
        }
        for (let l = 0; l < layerY.length; l++) {
          const pointActive = selected < 0 || selected === l || selected === l + 1;
          const mesh = snap.points[cls][i][l];
          mesh.material = isHover ? dotMaterials[cls].active : (pointActive ? dotMaterials[cls].normal : dotMaterials[cls].dim);
          mesh.scale.setScalar(isHover ? 1.75 : (emphasized ? 1.16 : 0.96));
        }
      }
    }
  });

  document.querySelectorAll('#forwardPassLayerButtons button').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.layer === forwardPassLayer);
  });
}

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.94,
  target: [0.08, 2.48, -0.14],
  distanceScale: 1.22
});

for (let gap = 0; gap < 6; gap++) {
  const entry = addLabel(opNames[gap], new THREE.Vector3(labelAnchor.x, (layerY[gap] + layerY[gap + 1]) / 2, labelAnchor.z), {
    fontSize: '14px',
    background: '#ffffff',
    offset: [-2, 0]
  });
  entry.div.style.border = '2px solid #000';
  entry.div.style.borderRadius = '8px';
  entry.div.style.padding = '1px 9px';
  entry.div.style.fontFamily = 'ui-monospace, Menlo, Consolas, monospace';
}

addLabel('Training iteration', axisStart.clone().addScaledVector(screenRight, -0.42), {
  fontSize: '20px',
  bold: true,
  offset: [0, 12]
});
addLabel('&bull;&nbsp;&bull;&nbsp;&bull;', centerForSnapshot(0).lerp(centerForSnapshot(1), 0.60).setY(axisY).addScaledVector(screenDepth, 0.88), {
  fontSize: '24px',
  bold: true,
  offset: [0, 9]
});
addLabel('&bull;&nbsp;&bull;&nbsp;&bull;', centerForSnapshot(2).lerp(centerForSnapshot(3), 0.44).setY(axisY).addScaledVector(screenDepth, 0.88), {
  fontSize: '24px',
  bold: true,
  offset: [0, 9]
});

const localRaycaster = new THREE.Raycaster();
const localPointer = new THREE.Vector2();
canvas.addEventListener('pointermove', (event) => {
  const rect = canvas.getBoundingClientRect();
  localPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  localPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  localRaycaster.setFromCamera(localPointer, camera);
  const hits = localRaycaster.intersectObjects(allPointMeshes, false);
  if (hits.length) {
    const o = hits[0].object;
    const next = { snap: o.userData.snap, cls: o.userData.pointClass, i: o.userData.pointIndex };
    if (!hoverRef || hoverRef.snap !== next.snap || hoverRef.cls !== next.cls || hoverRef.i !== next.i) {
      hoverRef = next;
      updateHoverTrace();
      refreshStyles();
    }
    showTooltip(`${next.cls} example ${next.i + 1}, iteration ${snapshotIters[next.snap]}: traced through all seven planes`, event);
  } else if (hoverRef) {
    hoverRef = null;
    updateHoverTrace();
    refreshStyles();
  }
});
canvas.addEventListener('pointerleave', () => {
  hoverRef = null;
  updateHoverTrace();
  refreshStyles();
});

document.getElementById('trainingIteration').addEventListener('input', (e) => {
  highlightedIteration = Number(e.target.value);
  refreshStyles();
});
document.querySelectorAll('#forwardPassLayerButtons button').forEach(btn => {
  btn.addEventListener('click', () => {
    forwardPassLayer = btn.dataset.layer;
    refreshStyles();
  });
});

const demoSteps = [
  {
    iter: 0,
    layer: 'allLayers',
    title: 'Early training: tangled activations',
    body: 'The leftmost stack shows early training, where red and blue representations are still tangled and mostly travel upward through a narrow column.'
  },
  {
    iter: 33,
    layer: 'linear1',
    title: 'First separation begins',
    body: 'The highlighted incoming layer segment shows how an early linear map starts pulling the two classes into different slanted bundles.'
  },
  {
    iter: 66,
    layer: 'relu2',
    title: 'The blue fan opens outward',
    body: 'By the third snapshot, the blue trajectories form a large outward fan while the red paths collect into an opposing bundle. The ReLU slice emphasizes the kinked, non-linear reshaping.'
  },
  {
    iter: 100,
    layer: 'softmax',
    title: 'Late training: clean class split',
    body: 'The final snapshot shows a strong class split: blue examples sweep broadly to the right and red examples gather to the opposite side before the softmax layer.'
  }
];

let tweenToken = 0;
window.goToStep = function goToStep(stepIndex = 0) {
  const step = demoSteps[Math.max(0, Math.min(demoSteps.length - 1, stepIndex | 0))];
  const startIter = highlightedIteration;
  const endIter = step.iter;
  const start = performance.now();
  const token = ++tweenToken;
  forwardPassLayer = step.layer;
  showPopup(step.title, step.body);
  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - start) / 650);
    const s = t * t * (3 - 2 * t);
    highlightedIteration = startIter + (endIter - startIter) * s;
    document.getElementById('trainingIteration').value = String(Math.round(highlightedIteration));
    refreshStyles();
    if (t < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
};
document.querySelectorAll('#demoStepButtons button').forEach(btn => {
  btn.addEventListener('click', () => window.goToStep(Number(btn.dataset.step)));
});

refreshStyles();
// @FIGURE_CODE_END

